  getVariants(sessionId: string): ActiveVariantSnapshot[] {
    const resources = this.resources.get(sessionId);
    return this.store.getVariants(sessionId).map((variant) => {
      const port = this.getDevServerPort(sessionId, variant.workItemId);
      const capturedDiff = this.workspaceInventory.getWorktree(
        sessionId,
        variant.workItemId,
      )?.diff;
      const changedFilesCount =
        typeof capturedDiff === 'string' && capturedDiff.length > 0
          ? countDiffFiles(capturedDiff)
          : undefined;
      const staticPreview =
        this.workspaceInventory.getStaticPreview(
          sessionId,
          variant.workItemId,
        ) ?? this.getStaticPreviewByBriefId(sessionId, variant.briefId);
      let preview: ActiveVariantSnapshot['preview'];
      if (staticPreview) {
        preview = {
          kind: 'static_artifact',
          url: this.buildStaticPreviewUrl(sessionId, staticPreview.workItemId),
        };
      } else if (!port) {
        try {
          const output = this.store.getWorkItemOutput(
            sessionId,
            variant.workItemId,
          ) as { html?: string } | null | undefined;
          if (typeof output?.html === 'string' && output.html.length > 0) {
            preview = {
              kind: 'static_artifact',
              url: this.buildStaticPreviewUrl(sessionId, variant.workItemId),
            };
          }
        } catch {}
      }
      if (!preview && port) {
        preview = { kind: 'dev_server', port };
      }
      const qa = resources?.qaResults.get(variant.workItemId);
      const isSucceeded = variant.status === 'succeeded';
      const canView = Boolean(preview) || (isSucceeded && Boolean(port));
      const previewFailure = this.previewRuntime.getFailure(
        sessionId,
        variant.workItemId,
      );
      const previewUnavailable =
        !canView && isSucceeded && previewFailure
          ? {
              ...previewFailure,
              portInUse: previewFailure.portInUse || undefined,
            }
          : undefined;
      return {
        ...variant,
        design: enrichDesignSource(variant.design),
        ...(preview ? { preview } : {}),
        port,
        ...(changedFilesCount !== undefined ? { changedFilesCount } : {}),
        ...(qa ? { qa } : {}),
        ...(previewUnavailable ? { previewUnavailable } : {}),
        actions: {
          view: canView
            ? { enabled: true }
            : {
                enabled: false,
                reason: buildViewDisabledReason({
                  status: variant.status,
                  isSucceeded,
                  qa,
                }),
              },
        },
      };
    });
  }

